#!/bin/bash
# Regenerate the n = 7 data files of this proof from the certificate in wang/certs/n7/.
#
# usage: tools/make_n7.sh CERTDIR [JOBS]
#
# CERTDIR holds n7_D17_sNNN.{tree,tori}.xz and SHA256SUMS (wang/certs/n7 in this repository, 195 MB).
# Checks SHA256SUMS, then writes n7/Cert7_sNNN.v (the tree bytes and tori of shard NNN as Rocq data,
# with the SHA-256 of the files read in the header) and n7/Check7_sNNN.v (the lemma that shard NNN
# passes), and finally compares the generated files with n7/MANIFEST.sha256 when that exists.
# n7/Wang7_Prefixes.v is kept in the repository; tools/c/prefixes.c regenerates its input.
set -e
here=$(cd "$(dirname "$0")/.." && pwd)
certs=$(cd "$1" && pwd)
jobs=${2:-4}
(cd "$certs" && sha256sum --quiet -c SHA256SUMS)
echo "certificate files match SHA256SUMS"
mkdir -p "$here/n7"
for s in $(seq -f %03g 0 63); do
  while [ "$(jobs -rp | wc -l)" -ge "$jobs" ]; do wait -n; done
  ( python3 "$here/tools/cert_to_coq.py" "$certs/n7_D17_s$s" "cert7_s$s" "$here/n7/Cert7_s$s.v" > /dev/null
    cat > "$here/n7/Check7_s$s.v" <<V
(* generated by tools/make_n7.sh *)
From WangTiles Require Import Wang_Checker.
From WangTiles.n7 Require Import Wang7_Prefixes Cert7_s$s.

(** Shard $s of the n = 7, D = 17 certificate passes the checker. *)
Lemma shard7_s${s}_ok : check refs7 cert7_s$s = true.
Proof. native_cast_no_check (eq_refl true). Time Qed.
V
  ) &
done
wait
cd "$here/n7"
if [ -f MANIFEST.sha256 ]; then
  sha256sum --quiet -c MANIFEST.sha256 && echo "generated files match n7/MANIFEST.sha256"
else
  sha256sum Cert7_s*.v Check7_s*.v > MANIFEST.sha256
  echo "wrote n7/MANIFEST.sha256"
fi
